#include "track_editor.hpp"
#include "captured_scene.hpp"
#include "course_ui.hpp"
#include "file_io.hpp"
#include <iostream>
int main(int argc,char**argv){try{using namespace ofo;Resources r(argv[1]);r.mount(fs::path(argv[2])/"capture_assets","capture_assets");auto g=load_geometry(r,"tracks/forest/forest1/geometry/track_geom.w32");auto capture=append_captured_scene(g,r);auto list=track_templates(g);if(list.empty())throw std::runtime_error("Native editor templates missing");TrackDocument d;d.stage="tracks/forest/forest1/a";auto course=race_course(r,d.stage);for(auto&p:course.at("points"))d.route.push_back({p[0],p[1],p[2]});auto native=g.props.at(list[0].source_prop);d.placements.push_back({list[0].source_prop,{native.transform[12]+5,native.transform[13],native.transform[14]},.3f});size_t before=g.props.size();apply_track_document(g,d);if(g.props.back().mass!=native.mass||g.props.back().inertia.x!=native.inertia.x)throw std::runtime_error("Native editor clone physics mismatch");fs::path out(argv[3]);save_track_document(out,d);save_track_minimap(out,d);Json report={{"native_instances",before},{"templates",list.size()},{"instances_after_custom_placement",g.props.size()},{"native_mass_preserved",g.props.back().mass},{"route_points",d.route.size()},{"minimap_size",512},{"runtime_gpu_verified",false}};write_file_atomic(out/"editor_native_audit.json",report.dump(2));std::cout<<report.dump(2)<<'\n';}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
